package com.chartboost.monetization.kotlin.validator

import android.os.Bundle
import android.util.Log
import android.widget.FrameLayout
import androidx.appcompat.app.AppCompatActivity
import com.chartboost.monetization.kotlin.validator.databinding.ActivityMainBinding
import com.chartboost.sdk.Chartboost
import com.chartboost.sdk.ads.Banner
import com.chartboost.sdk.ads.Interstitial
import com.chartboost.sdk.ads.Rewarded
import com.chartboost.sdk.callbacks.BannerCallback
import com.chartboost.sdk.callbacks.InterstitialCallback
import com.chartboost.sdk.callbacks.RewardedCallback
import com.chartboost.sdk.events.CacheError
import com.chartboost.sdk.events.CacheEvent
import com.chartboost.sdk.events.ClickError
import com.chartboost.sdk.events.ClickEvent
import com.chartboost.sdk.events.DismissEvent
import com.chartboost.sdk.events.ImpressionEvent
import com.chartboost.sdk.events.RewardEvent
import com.chartboost.sdk.events.ShowError
import com.chartboost.sdk.events.ShowEvent

class MainActivity : AppCompatActivity() {
    private lateinit var binding: ActivityMainBinding
    private val logTag = "[ChartboostMonetizationValidator]"

    private var interstitial: Interstitial? = null
    private var rewarded: Rewarded? = null
    private var banner: Banner? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        Chartboost.startWithAppId(
            this,
            "4f7b433509b6025804000002",
            "0b04e963321bc0480352044439c381d1b54a43f8",
        ) {
            Log.i(logTag, "Chartboost SDK initialized")
        }

        setupButtonClickListeners()
    }

    private fun setupButtonClickListeners() {
        binding.loadBannerButton.setOnClickListener {
            loadBannerAd()
        }

        binding.loadInterstitialButton.setOnClickListener {
            loadInterstitialAd()
        }

        binding.showInterstitialButton.setOnClickListener {
            interstitial?.show()
        }

        binding.loadRewardedButton.setOnClickListener {
            loadRewardedAd()
        }

        binding.showRewardedButton.setOnClickListener {
            rewarded?.show()
        }
    }

    private fun loadBannerAd() {
        banner?.detach()
        val bannerContainer = findViewById<FrameLayout>(R.id.banner_container)
        banner =
            Banner(
                this,
                "default",
                Banner.BannerSize.STANDARD,
                object : BannerCallback {
                    override fun onAdLoaded(
                        event: CacheEvent,
                        error: CacheError?,
                    ) {
                        error?.let {
                            Log.e(logTag, "Banner load error: ${it.code}")
                        } ?: run {
                            Log.i(logTag, "Banner loaded successfully")
                            banner?.show()
                            bannerContainer.removeAllViews()
                            banner?.let { bannerAd ->
                                bannerContainer.addView(
                                    bannerAd,
                                    FrameLayout.LayoutParams(
                                        FrameLayout.LayoutParams.MATCH_PARENT,
                                        FrameLayout.LayoutParams.WRAP_CONTENT,
                                    ),
                                )
                            }
                        }
                    }

                    override fun onAdRequestedToShow(event: ShowEvent) {
                        Log.i(logTag, "Banner ad requested to show")
                    }

                    override fun onAdShown(
                        event: ShowEvent,
                        error: ShowError?,
                    ) {
                        error?.let {
                            Log.e(logTag, "Banner show error: ${it.code}")
                        } ?: run {
                            Log.i(logTag, "Banner ad shown")
                        }
                    }

                    override fun onAdClicked(
                        event: ClickEvent,
                        error: ClickError?,
                    ) {
                        error?.let {
                            Log.e(logTag, "Banner click error: ${it.code}")
                        } ?: run {
                            Log.i(logTag, "Banner ad clicked")
                        }
                    }

                    override fun onImpressionRecorded(event: ImpressionEvent) {
                        Log.i(logTag, "Banner impression recorded")
                    }
                },
            )
        banner?.cache(
            "",
        )
    }

    private fun loadInterstitialAd() {
        interstitial =
            Interstitial(
                "default",
                object : InterstitialCallback {
                    override fun onAdDismiss(event: DismissEvent) {
                        Log.i(logTag, "Interstitial ad dismissed")
                    }

                    override fun onAdLoaded(
                        event: CacheEvent,
                        error: CacheError?,
                    ) {
                        error?.let {
                            Log.e(logTag, "Interstitial load error: ${it.code}")
                        } ?: run {
                            Log.i(logTag, "Interstitial loaded successfully")
                        }
                    }

                    override fun onAdRequestedToShow(event: ShowEvent) {
                        Log.i(logTag, "Interstitial ad requested to show")
                    }

                    override fun onAdShown(
                        event: ShowEvent,
                        error: ShowError?,
                    ) {
                        error?.let {
                            Log.e(logTag, "Interstitial show error: ${it.code}")
                        } ?: run {
                            Log.i(logTag, "Interstitial ad shown")
                        }
                    }

                    override fun onAdClicked(
                        event: ClickEvent,
                        error: ClickError?,
                    ) {
                        error?.let {
                            Log.e(logTag, "Interstitial click error: ${it.code}")
                        } ?: run {
                            Log.i(logTag, "Interstitial ad clicked")
                        }
                    }

                    override fun onImpressionRecorded(event: ImpressionEvent) {
                        Log.i(logTag, "Interstitial impression recorded")
                    }
                },
            )
        interstitial?.cache(
            "",
        )
    }

    private fun loadRewardedAd() {
        rewarded =
            Rewarded(
                "default",
                object : RewardedCallback {
                    override fun onRewardEarned(event: RewardEvent) {
                        Log.i(logTag, "Reward earned: ${event.reward}")
                    }

                    override fun onAdDismiss(event: DismissEvent) {
                        Log.i(logTag, "Rewarded ad dismissed")
                    }

                    override fun onAdLoaded(
                        event: CacheEvent,
                        error: CacheError?,
                    ) {
                        if (error != null) {
                            Log.e(logTag, "Rewarded load error: ${error.code}")
                        } else {
                            Log.i(logTag, "Rewarded ad loaded successfully")
                        }
                    }

                    override fun onAdRequestedToShow(event: ShowEvent) {
                        Log.i(logTag, "Rewarded ad requested to show")
                    }

                    override fun onAdShown(
                        event: ShowEvent,
                        error: ShowError?,
                    ) {
                        if (error != null) {
                            Log.e(logTag, "Rewarded show error: ${error.code}")
                        } else {
                            Log.i(logTag, "Rewarded ad shown")
                        }
                    }

                    override fun onAdClicked(
                        event: ClickEvent,
                        error: ClickError?,
                    ) {
                        if (error != null) {
                            Log.e(logTag, "Rewarded click error: ${error.code}")
                        } else {
                            Log.i(logTag, "Rewarded ad clicked")
                        }
                    }

                    override fun onImpressionRecorded(event: ImpressionEvent) {
                        Log.i(logTag, "Rewarded impression recorded")
                    }
                },
            )
        rewarded?.cache(
            "",
        )
    }
}
